import{_ as i,o as e,c as a,aO as l}from"./chunks/framework.BFrk9dwu.js";const o="/recipes/sauerkraut-fish.jpg",r="/recipes/sauerkraut-fish/top-2.jpg",d="/recipes/sauerkraut-fish/top-3.jpg",s="/recipes/sauerkraut-fish/step-2-a.jpg",p="/recipes/sauerkraut-fish/step-1-a.jpg",n="/recipes/sauerkraut-fish/step-1-b.jpg",g="/recipes/sauerkraut-fish/step-3-a.jpg",c="/recipes/sauerkraut-fish/step-6-a.jpg",u="/recipes/sauerkraut-fish/step-6-b.jpg",h="/recipes/sauerkraut-fish/step-7-a.jpg",q=JSON.parse('{"title":"酸菜鱼","description":"鱼片上浆静置、酸菜炒干、汤微沸下鱼片的酸菜鱼做法，含脱浆、发柴、汤寡的排查","frontmatter":{"title":"酸菜鱼","date":"2026-11-12T23:40:00.000Z","description":"鱼片上浆静置、酸菜炒干、汤微沸下鱼片的酸菜鱼做法，含脱浆、发柴、汤寡的排查","permalink":"/pages/7d7335","categories":["life","recipes"]},"headers":[],"relativePath":"life/recipes/sauerkraut-fish.md","filePath":"life/recipes/sauerkraut-fish.md","lastUpdated":null}'),m={name:"life/recipes/sauerkraut-fish.md"};function f(_,t,b,k,y,j){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="酸菜鱼" tabindex="-1">酸菜鱼 <a class="header-anchor" href="#酸菜鱼" aria-label="Permalink to &quot;酸菜鱼&quot;">​</a></h1><div class="recipe-gallery"><img src="'+o+'" alt="酸菜鱼成品：白瓷盆里一层红油，雪白鱼片铺在酸菜上，撒了辣椒段和花椒"><img src="'+r+'" alt="俯拍汤面特写：鱼片、酸菜丝、青花椒和蒜末浮在红油上"><img src="'+d+'" alt="盛在小碗里，筷子夹起一片鱼片，旁边一碗白米饭"><img src="'+s+'" alt="原料摆拍：生鱼片"></div><p>这道菜分三段落：鱼片上浆、酸菜炒香、汤里滑鱼片。前两段决定味道，第三段决定口感——鱼片下锅只有 30~40 秒，汤一大滚就全毁了。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>草鱼或黑鱼</td><td>黑鱼肉更紧、刺少，草鱼便宜；让摊主片好</td></tr><tr><td>老坛酸菜</td><td>用酸菜鱼专用袋装酸菜，别拿榨菜凑</td></tr><tr><td>泡野山椒</td><td>酸辣的那层「辣」主要靠它</td></tr><tr><td>泡姜</td><td>没有就用普通姜片</td></tr></tbody></table><p><strong>上浆</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>盐</td><td>抓出黏性，是上浆的第一步</td></tr><tr><td>料酒</td><td>去腥</td></tr><tr><td>白胡椒粉</td><td></td></tr><tr><td>蛋清</td><td>只要蛋清，蛋黄会让汤浑</td></tr><tr><td>玉米淀粉</td><td>最后裹上，锁住水分</td></tr></tbody></table><p><strong>汤与泼油</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>食用油</td><td></td></tr><tr><td>姜</td><td></td></tr><tr><td>大蒜</td><td></td></tr><tr><td>高汤或清水</td><td></td></tr><tr><td>盐</td><td>适量，酸菜本身咸，尝过再补</td></tr><tr><td>干辣椒段</td><td>泼油用</td></tr><tr><td>花椒</td><td>泼油用，青花椒更香</td></tr><tr><td>热油</td><td>最后泼的那一下</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>片鱼。</strong> 让摊主把鱼片好：鱼头鱼骨剁成块，鱼肉斜刀片成 3mm 左右、约两指宽的片。自己片的话，鱼身半冷冻半小时更好切。</p><figure class="recipe-shots"><img loading="lazy" src="'+p+'" alt="案板上一条完整草鱼和一把菜刀"><img loading="lazy" src="'+n+'" alt="片好的鱼片平铺在白盘里，厚薄均匀"></figure></li><li><p><strong>冲水去腥。</strong> 鱼片用流动水冲 2 分钟，冲到水清、鱼肉发白，然后彻底沥干、用厨房纸吸干水分。<strong>带水下浆会脱浆</strong>，这一步别省。</p><figure class="recipe-shots"><img loading="lazy" src="'+s+'" alt="冲水去腥"></figure></li><li><p><strong>上浆。</strong> 鱼片加盐、料酒、白胡椒粉，抓 30 秒抓到发黏；加 1 个蛋清抓匀；最后撒淀粉裹匀，冷藏静置 10~15 分钟。</p><figure class="recipe-shots"><img loading="lazy" src="'+g+'" alt="上浆"></figure></li><li><p><strong>炒酸菜。</strong> 酸菜挤干水分（挤出的小半碗水直接倒掉，留着会把汤冲淡），切段。锅下油，姜片、拍碎的蒜炒香，下酸菜中火炒 3~4 分钟，炒到水分收干、边缘微微焦黄。</p><ul><li>酸菜的香气是炒出来的，不炒直接下汤，汤就是一股咸酸水味。</li></ul></li><li><p><strong>加泡椒。</strong> 下泡野山椒、泡姜再炒 1 分钟，辣味和发酵的酸香出来。</p></li><li><p><strong>熬汤。</strong> 鱼头鱼骨下锅一起翻炒 2 分钟，倒高汤或清水，大火烧开转中火煮 8 分钟，汤色发白。加白胡椒粉，尝一下咸淡再决定加不加盐。</p><figure class="recipe-shots"><img loading="lazy" src="'+c+'" alt="熬汤"><img loading="lazy" src="'+u+'" alt="熬汤"></figure></li><li><p><strong>滑鱼片。</strong> 汤重新烧到<strong>微沸</strong>（表面小泡、不翻滚），鱼片逐片下锅，用筷子轻轻点开，别搅。30~40 秒，鱼片变白、边缘卷起就关火，连汤倒进盆中。</p><figure class="recipe-shots"><img loading="lazy" src="'+h+'" alt="滑鱼片"></figure></li><li><p><strong>泼油。</strong> 表面撒蒜末、干辣椒段、花椒。另起锅烧油到冒大烟，直接浇在料上，「呲」一声，香气才出得来。</p><figure class="recipe-shots"><img loading="lazy" src="'+r+'" alt="泼油"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>鱼片 3mm + 上浆静置</strong>：厚度决定嫩度，淀粉和蛋清是那层保护膜，静置 10 分钟才贴得牢。</li><li><strong>酸菜必须挤干再炒</strong>：挤水、炒干、炒出香味，三步一体，少一步汤就寡。</li><li><strong>下鱼片时汤只能微沸</strong>：大滚的汤会把浆冲散，鱼片又碎又柴。全程别用铲子翻。</li><li><strong>泼油温度要够</strong>：油冒大烟再浇，温油浇上去只有一层油，没有香气。</li><li>想更麻，泼油时花椒加到 8g，另加 3g 花椒粉最后撒。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">偷懒版</p><p>超市有现成的酸菜鱼调料包，酸菜、泡椒、腌鱼料都配好了。买一包黑鱼片，按包装比例上浆，炒酸菜和微沸滑片这两步，味道差不太多，时间能省一半。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>鱼片脱浆、碎成一片</strong>：汤大滚下锅，或者下锅后拿铲子搅。</li><li><strong>鱼片又老又柴</strong>：煮过头，超过 1 分钟基本就废了。</li><li><strong>汤发酸、寡淡</strong>：酸菜没挤水、没炒香，直接下汤煮。</li><li><strong>腥味重</strong>：鱼片没冲血水，或者鱼骨没煮够时间。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',17)])])}const v=i(m,[["render",f]]);export{q as __pageData,v as default};
